use crate::{bq063 as b,catalog,deck,model::*,rules::*,unit_support::*};
fn setup(parked:bool)->(Game,String,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let c=g.make_card("BQ046",0);let core=c.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:if parked{Some(c.clone())}else{None}});if !parked{g.regions[0].cards.push(c);}fund(&mut g,0,"JC069",3);let id=held(&mut g,b::ID,0);(g,id,core)}
fn play(id:&str,mode:&str)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),option:Some(mode.into()),..Action::new("play")}}
fn forecast(g:&mut Game){let p=g.pending.clone().unwrap();let ids=p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>();assert!(matches!(p.resolution,ChoiceResolution::Frame{choice:FrameChoice::BQ063Forecast{..},..}));act(g,p.seat,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});}
fn invalid(reference:&Game,g:&Game){let s=serde_json::to_string(g).unwrap();assert!(Game::from_persisted(&s).is_err());let mut room=crate::jc029_tests::envelope(reference);room.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}
#[test]
fn bq063_original_formal_gray_closed_complete_modes_and_society_gate(){let c=catalog::card(b::ID);assert_eq!((c.cost,c.color.as_str(),c.supported),(3,"灰",false));assert_eq!(c.subtypes,["命令","精神"]);assert_eq!(b::definition().abilities[0].modes.len(),3);for n in 0..3{let mut d=b::definition();d.abilities[0].modes[n].ops.pop();assert!(b::validate_definition(b::ID,&d).is_err());}let(mut g,id,_)=setup(true);let society=g.players[0].society_zone.card.take();reject(&mut g,0,play(&id,"core"));g.players[0].society_zone.card=society;for mode in ["", "ready", "hide,core"]{reject(&mut g,0,play(&id,mode));}let mut a=play(&id,"hide");a.target_id=Some("region:0".into());reject(&mut g,0,a);reject(&mut g,0,Action{card_id:Some(id),ability_id:Some(b::KEY.into()),..Action::new("activate")});assert_eq!(g.resources(0),3);}
#[test]
fn bq063_two_actual_forecasts_before_repression_core_zone_and_board(){for parked in [false,true]{let(mut g,id,_)=setup(parked);act(&mut g,0,play(&id,"core"));assert_eq!(g.resources(0),0);crate::jc029_tests::pass_top(&mut g);assert!(matches!(g.pending.as_ref().unwrap().resolution,ChoiceResolution::Frame{choice:FrameChoice::BQ063Forecast{..},..}));restore(&mut g);forecast(&mut g);assert!(matches!(g.pending.as_ref().unwrap().resolution,ChoiceResolution::Frame{choice:FrameChoice::BQ063Forecast{..},..}));restore(&mut g);forecast(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq063-opponent");assert_eq!(g.players[0].honor,0);resolve_choice(&mut g);assert!(g.pending.is_none());restore(&mut g);}}
#[test]
fn bq063_hide_reads_response_region_and_hides_own_core_without_losing_sweep(){for moved in [false,true]{let(mut g,id,core)=setup(false);let a=field(&mut g,"JC125",1);let z=field(&mut g,"JC125",2);let c=g.regions[0].cards.pop().unwrap();g.regions[1].cards.push(c);act(&mut g,0,play(&id,"hide"));if moved{g.move_on_board_instance(&core,1);}restore(&mut g);crate::jc029_tests::pass_top(&mut g);assert!(g.board(&core).is_none());let hidden=g.regions[if moved{1}else{0}].cards.iter().filter(|c|c.face_down).count();assert_eq!(hidden,2);assert_eq!(g.board(&a).is_some(),moved);assert_eq!(g.board(&z).is_some(),!moved);assert!(g.regions[if moved{0}else{1}].cards.iter().all(|c|!c.face_down));restore(&mut g);}}
#[test]
fn bq063_return_targets_all_hidden_owners_only_in_current_core_region(){let(mut g,id,_)=setup(false);let first=field(&mut g,"JC125",1);g.hide_in_place(&first);let second=field(&mut g,"JC125",2);g.hide_in_place(&second);let far=field(&mut g,"JC125",3);let c=g.regions[0].cards.pop().unwrap();g.regions[1].cards.push(c);g.hide_in_place(&far);let before=[g.players[1].hand.len(),g.players[2].hand.len(),g.players[3].hand.len()];act(&mut g,0,play(&id,"return"));crate::jc029_tests::pass_top(&mut g);assert_eq!(g.players[1].hand.len(),before[0]+1);assert_eq!(g.players[2].hand.len(),before[1]+1);assert_eq!(g.players[3].hand.len(),before[2]);assert!(g.regions[1].cards.iter().any(|c|c.face_down));restore(&mut g);}
#[test]
fn bq063_no_core_still_represses_and_enemy_chooses_actual_influence(){let(mut g,id,core)=setup(false);g.hide_in_place(&core);g.regions[0].influence[1]=2;act(&mut g,0,play(&id,"core"));crate::jc029_tests::pass_top(&mut g);let p=g.pending.clone().unwrap();assert_eq!(p.choice.kind,"bq063-opponent");let enemy=p.choice.options[0].id.clone();let seat=enemy[1..].parse::<usize>().unwrap();act(&mut g,0,Action{choice_id:Some(p.choice.id),selected:Some(vec![enemy]),..Action::new("choose")});assert_eq!(g.pending.as_ref().unwrap().seat,seat);restore(&mut g);resolve_choice(&mut g);assert_eq!(g.regions[0].influence[1],1);assert!(g.pending.is_none());restore(&mut g);}
#[test]
fn bq063_corrupt_source_modes_payments_missing_and_duplicate_continuations_reject(){let(mut g,id,_)=setup(true);act(&mut g,0,play(&id,"core"));for n in 0..5{let mut bad=g.clone();let i=bad.stack.last_mut().unwrap();if n==0{i.frame=None;}else{let f=i.frame.as_mut().unwrap();match n{1=>f.source.card.definition="JC001".into(),2=>{f.steps.remove(0);},3=>f.already_paid.clear(),_=>f.steps[0].context=1}}invalid(&g,&bad);}crate::jc029_tests::pass_top(&mut g);let frame=match &g.pending.as_ref().unwrap().resolution{ChoiceResolution::Frame{frame,..}=>frame.clone(),_=>panic!("missing paid forecast frame")};let mut duplicate=g.clone();duplicate.effects.push_back(Effect::Frame{frame});invalid(&g,&duplicate);forecast(&mut g);forecast(&mut g);for n in 0..4{let mut bad=g.clone();let p=bad.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(0),1=>p.choice.options.push(ChoiceOption{id:"p0".into(),label:"self".into(),card:None}),2=>p.choice.kind="forecast".into(),_=>{if let ChoiceResolution::Frame{frame,..}=&mut p.resolution{frame.cursor=1;}}}invalid(&g,&bad);}restore(&mut g);}

fn constructed(seed:u64)->(Game,deck::DeckDraft){
 let mut d=deck::preset("watchers").unwrap();d.id="closed-bq063-50-plus-core".into();d.name="神话威严私有50+1".into();d.description="50张普通牌及独立核心；非官方预组".into();d.society_id=Some("MSBQ02".into());d.core_card_id=Some("BQ046".into());d.cards=[("BQ064",3),("BQ048",3),("BQ050",3),("BQ063",3),("JC125",38)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if ["BQ046","BQ048","BQ050","BQ063"].contains(&c.id.as_str()){c.supported=true;}}let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSBQ02").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();
 let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq063-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)
}
fn choose_trace(t:&mut crate::abi112_review_play_tests::Trace)->bool{
 let Some(p)=t.room.game.pending.clone()else{return false;};
 if matches!(p.resolution,ChoiceResolution::Frame{choice:FrameChoice::BQ063Forecast{..},..}){let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});}
 else {t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}true
}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let cmd=serde_json::from_value(s["command"].clone()).unwrap();let d=room.transition(s["seat"].as_u64().unwrap()as usize,Some(cmd),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn natural()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(seed,g,d)=(1..1025).find_map(|seed|{let(g,d)=constructed(seed);let h=&g.players[0].hand;(h.iter().filter(|c|c.definition==b::ID).count()>=2&&h.iter().filter(|c|c.definition=="JC125").count()>=2).then_some((seed,g,d))}).expect("bounded real initial hand");let mut t=Trace::new_preserving_rng(g,"bq063-natural-50-plus-core-two-forecasts".into(),670);let mut played=false;let mut forecasts=0;let mut done=false;
 for _ in 0..900{if t.room.game.pending.as_ref().is_some_and(|p|matches!(p.resolution,ChoiceResolution::Frame{choice:FrameChoice::BQ063Forecast{..},..})){forecasts+=1;}if choose_trace(&mut t){continue;}if played&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){done=true;break;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.len()<3{let desired=if g.players[0].assets.is_empty(){b::ID}else{"JC125"};legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==desired)))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY)&&a.action.option.as_deref()==Some("core"))};if let Some(a)=a{if a.action.kind=="play"{played=true;}t.action(0,a.action.clone());}else{t.pass();}}
 assert!(done);assert_eq!(forecasts,2);assert_eq!(t.room.game.players[0].honor,0);let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"ordinaryCards":50,"separateCore":1,"minimumCommandCards":12,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)
}
fn prepared(mode:&str,index:usize)->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(mut g,id,_)=setup(false);field(&mut g,"JC125",1);if mode=="return"{let victim=field(&mut g,"JC125",2);g.hide_in_place(&victim);}g.regions[0].influence[1]=1;let mut t=Trace::new_preserving_rng(g,format!("bq063-prepared-{mode}-and-repress"),index);t.action(0,play(&id,mode));for _ in 0..64{if choose_trace(&mut t){continue;}if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}t.pass();}assert!(t.room.game.pending.is_none()&&t.room.game.stack.is_empty());assert_eq!(t.room.game.regions[0].influence[1],0);duplicate(t.value())}
#[test]
fn bq063_natural_fifty_plus_core_and_prepared_modes_export(){let cases=vec![natural(),prepared("hide",671),prepared("return",672)];if let Ok(path)=std::env::var("BQ063_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":source_bindings(),"cases":cases})).unwrap()).unwrap();}}
fn source_bindings()->serde_json::Value{use sha2::{Digest,Sha256};let mut b=crate::shoggoth_tests::shoggoth_source_bindings();for(n,bytes)in[("rust-game/src/bq063.rs",include_bytes!("bq063.rs").as_slice()),("rust-game/src/bq063_tests.rs",include_bytes!("bq063_tests.rs").as_slice())]{b["files"].as_object_mut().unwrap().insert(n.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}b}

#[test]
fn bq063_first_core_forecast_cannot_resume_as_second(){
 let(mut g,id,_)=setup(true);act(&mut g,0,play(&id,"core"));crate::jc029_tests::pass_top(&mut g);
 let mut bad=g.clone();
 if let Some(Pending{resolution:ChoiceResolution::Frame{frame,..},..})=&mut bad.pending {frame.cursor=2;}
 else {let f=bad.effects.iter_mut().find_map(|e|if let Effect::Frame{frame}=e{Some(frame)}else{None}).unwrap();assert_eq!(f.cursor,1);f.cursor=2;}
 invalid(&g,&bad);
 let mut detached=g.clone();let p=detached.pending.as_mut().unwrap();
 let ChoiceResolution::Frame{frame,..}=&p.resolution else{panic!("missing current bound forecast");};let frame=frame.clone();p.resolution=ChoiceResolution::Forecast{draw:false};detached.effects.push_front(Effect::Frame{frame});invalid(&g,&detached);
}

#[test]
fn bq063_forecast_partition_second_fresh_top_and_empty_deck_boundary(){
 let(mut g,id,_)=setup(true);act(&mut g,0,play(&id,"core"));crate::jc029_tests::pass_top(&mut g);
 let p=g.pending.clone().unwrap();let ids=p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>();let fourth=g.players[0].deck[3].id.clone();
 reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),top:Some(vec![ids[0].clone()]),bottom:Some(vec![]),..Action::new("choose")});
 for n in 0..4{let mut bad=g.clone();let p=bad.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(2),1=>{p.choice.options.pop();},_=>if let ChoiceResolution::Frame{choice:FrameChoice::BQ063Forecast{invocation,core,..},..}=&mut p.resolution{if n==2{*invocation=2;}else{core.card.owner=1;}}}invalid(&g,&bad);}
 act(&mut g,0,Action{choice_id:Some(p.choice.id),top:Some(vec![ids[1].clone(),ids[0].clone()]),bottom:Some(vec![ids[2].clone()]),..Action::new("choose")});
 assert_eq!(g.pending.as_ref().unwrap().choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>(),vec![ids[1].clone(),ids[0].clone(),fourth]);restore(&mut g);forecast(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq063-opponent");
 let(mut empty,id,_)=setup(true);empty.players[0].deck.clear();act(&mut empty,0,play(&id,"core"));crate::jc029_tests::pass_top(&mut empty);assert_eq!(empty.pending.as_ref().unwrap().choice.kind,"bq063-opponent");assert!(!empty.players[0].eliminated);restore(&mut empty);
}
